/** Su Bóveda (el DEV de la hija en GitHub Pages). null si no hay hija configurada. */
export function hijaBoveda(hija = CONFIG.hija) {
  if (!hija) return null;
  return hija.boveda || `https://${String(hija.owner).toLowerCase()}.github.io/${hija.repo}/`;
}

